/* Ciencia de datos (1): estadística descriptiva (tipos de variables, muestreo y sesgos, tablas de frecuencia, histogramas,
   correlación) y probabilidad (conteo, Bayes, variables aleatorias, binomial, Poisson, normal y límite central).
   Los numéricos usan datos al azar y comprobar() con un segundo cálculo (sumas directas, Simpson, simulación exacta). Sin DOM. */
import {prob,paso,final,marca,fmt,cerca,simpson,crearGen} from './extensiones/base.js';
import {bancoEn,KES,I} from './extensiones/ingles-base.js';

const NIV={1:['b1','b2','p1'],2:['b1','b2','p1','p2'],3:['p1','p2','a1'],4:['p1','p2','a1','a2'],5:['p2','a1','a2']};
const sum=a=>a.reduce((s,x)=>s+x,0),media=a=>sum(a)/a.length;
const fact=n=>n<=1?1:n*fact(n-1),C=(n,k)=>fact(n)/(fact(k)*fact(n-k)),Pm=(n,k)=>fact(n)/fact(n-k);
// Φ(z) con la aproximación de Abramowitz y Stegun (error < 1.5e-7); se comprueba integrando la densidad con Simpson
const phi=z=>{const t=1/(1+0.2316419*Math.abs(z)),d=Math.exp(-z*z/2)/Math.sqrt(2*Math.PI),p=d*t*(0.319381530+t*(-0.356563782+t*(1.781477937+t*(-1.821255978+t*1.330274429))));return z>=0?1-p:p};
const phiNum=z=>0.5+simpson(x=>Math.exp(-x*x/2)/Math.sqrt(2*Math.PI),0,z,2000);
const lista=a=>a.join(', ');

/* ---------- Tipos de variables ---------- */
const variables=bancoEn({titulo:'Tipos de variables',
  explicacion:'Una variable <b>numérica</b> mide una cantidad: <b>discreta</b> si se cuenta (número de hijos, de compras) y <b>continua</b> si se mide y puede tener decimales (estatura, tiempo, peso). Una <b>categórica</b> pone en grupos: <b>nominal</b> sin orden (color, país) u <b>ordinal</b> con orden (nivel de satisfacción, talla S/M/L). Un número que solo identifica (código postal, teléfono) es categórico.',
  alternativa:'Pregúntate: ¿tiene sentido sacar el promedio? Si sí, es numérica. Si no, categórica. Luego: ¿se cuenta o se mide? (discreta o continua) y ¿tiene orden? (ordinal o nominal).',
  referencia:'OpenIntro 1.2 – Datos: tipos de variables',regla:'Numérica: discreta (se cuenta) o continua (se mide). Categórica: nominal (sin orden) u ordinal (con orden). Códigos y teléfonos son categóricos.',pista:'¿Tiene sentido promediarla?',
  tarjetas:[['Variable discreta','Numérica que se cuenta (0, 1, 2…).'],['Variable continua','Numérica que se mide y admite decimales.'],['Variable ordinal','Categórica con orden (bajo, medio, alto).'],['¿Un código postal es numérico?','No: es categórico (solo identifica).']],
  plantillas:{
    b1:KES.dato([I('Número de hijos de una persona: ¿discreta o continua?',['discreta'],[['continua','Se cuenta: discreta.']]),I('Estatura en centímetros: ¿discreta o continua?',['continua'],[['discreta','Se mide y admite decimales: continua.']]),I('Color favorito: ¿nominal u ordinal?',['nominal'],[['ordinal','Los colores no tienen orden.']]),I('Nivel de satisfacción (bajo, medio, alto): ¿nominal u ordinal?',['ordinal'],[['nominal','Tiene orden.']])]),
    b2:KES.termino([I('Variable categórica cuyos grupos tienen un orden natural.',['ordinal'],[['nominal','Nominal no tiene orden.']]),I('Variable numérica que se obtiene contando.',['discreta'],[['continua','Contando: discreta.']]),I('Variable que pone a cada caso en un grupo (país, género, producto).',['categorica','categórica','cualitativa'],[['numerica','Agrupa: categórica.']])]),
    p1:KES.paso([I('Código postal: ¿numérica o categórica?',['categorica','categórica'],[['numerica','No tiene sentido promediarlo.']]),I('Tiempo de entrega en minutos: ¿numérica discreta, numérica continua o categórica?',['numerica continua','continua'],[['discreta','El tiempo se mide.']]),I('Talla de ropa (S, M, L, XL): ¿nominal u ordinal?',['ordinal'],[['nominal','S < M < L: tiene orden.']]),I('Número de quejas al día: ¿numérica discreta o continua?',['discreta','numerica discreta'],[['continua','Se cuentan.']])]),
    p2:KES.completa([I('Una variable con valores «sí» y «no» es categórica ___ (también llamada binaria).',['nominal'],[['ordinal','Sí/no no tiene orden.']]),I('El ingreso mensual en pesos es una variable numérica ___.',['continua'],[['discreta','Se trata como continua (medida en dinero).']]),I('Para una variable nominal tiene sentido calcular la ___, pero no la media.',['moda'],[['media','La media no tiene sentido en categorías.']])]),
    a1:KES.caso([I('Una encuesta pregunta «¿Qué tan probable es que nos recomiendes? (1 = nada, 5 = mucho)». ¿Qué tipo de variable es?',['ordinal','categorica ordinal'],[['continua','Es una escala con orden, no una medición continua.']]),I('Un hospital registra el tipo de sangre de cada paciente. ¿Qué tipo de variable es?',['nominal','categorica nominal'],[['ordinal','Los tipos de sangre no tienen orden.']]),I('Una tienda registra cuántos artículos compra cada cliente. ¿Qué tipo de variable es?',['numerica discreta','discreta'],[['continua','Se cuentan artículos.']])]),
    a2:KES.decide([I('Tienes la variable «región» (Norte, Sur, Centro). ¿Qué gráfica usas: histograma o barras?',['barras'],[['histograma','El histograma es para numéricas.']]),I('Tienes la variable «edad» de 500 clientes. ¿Qué gráfica usas para ver su distribución?',['histograma'],[['circular','Para una numérica: histograma.']]),I('Alguien calculó el «promedio del código postal» de los clientes. ¿Tiene sentido? (sí o no)',['no'],[['si','Es un identificador categórico.']])])
  }});

/* ---------- Muestreo y sesgos ---------- */
const muestreo=bancoEn({titulo:'Muestreo y sesgos',
  explicacion:'Una <b>muestra</b> representa a la <b>población</b> si se elige al azar. Tipos: <b>aleatorio simple</b> (todos con la misma probabilidad), <b>estratificado</b> (al azar dentro de grupos), <b>por conglomerados</b> (se eligen grupos completos al azar), <b>sistemático</b> (cada k-ésimo, k = N/n). La muestra <b>por conveniencia</b> (a quien esté a la mano) suele tener sesgo. Sesgos: de <b>selección</b>, de <b>no respuesta</b>, de <b>respuesta voluntaria</b> y de <b>supervivencia</b>. Solo un <b>experimento</b> con asignación aleatoria permite hablar de causa.',
  alternativa:'Probar la sopa: si la revuelves bien (al azar), una cucharada basta. Si solo pruebas la parte de arriba (conveniencia), puedes equivocarte.',
  referencia:'OpenIntro 1.3 – Muestreo: principios y estrategias',regla:'Aleatorio simple, estratificado, por conglomerados y sistemático (k = N/n). Conveniencia y respuesta voluntaria tienen sesgo. Causa solo con experimento aleatorizado.',pista:'¿Cómo se eligieron los casos?',
  tarjetas:[['Muestreo estratificado','Se divide la población en grupos y se elige al azar dentro de cada uno.'],['Muestreo sistemático','Se elige cada k-ésimo elemento, con k = N/n.'],['Sesgo de no respuesta','Los que no responden son distintos de los que sí.'],['¿Un estudio observacional prueba causa?','No: solo un experimento con asignación aleatoria.']],
  plantillas:{
    b1:KES.termino([I('Muestreo en el que cada persona tiene la misma probabilidad de ser elegida.',['aleatorio simple','muestreo aleatorio simple'],[['conveniencia','Conveniencia no es al azar.']]),I('Muestreo que elige al azar dentro de cada grupo (por ejemplo, por estado).',['estratificado','muestreo estratificado'],[['conglomerados','En conglomerados se eligen grupos completos.']]),I('Muestreo que elige grupos completos al azar (por ejemplo, 10 escuelas enteras).',['por conglomerados','conglomerados'],[['estratificado','Estratificado elige dentro de cada grupo.']])]),
    b2:KES.termino([I('Sesgo cuando muchos de los elegidos no contestan y son distintos de los que sí.',['no respuesta','sesgo de no respuesta'],[['seleccion','Es de no respuesta.']]),I('Sesgo de encuestas en línea donde solo opinan quienes quieren.',['respuesta voluntaria','sesgo de respuesta voluntaria','autoseleccion'],[['no respuesta','Es respuesta voluntaria.']]),I('Estudio en el que el investigador asigna los tratamientos al azar.',['experimento','experimento aleatorizado'],[['observacional','En el observacional no se asigna.']])]),
    p1:KES.paso([I('Población de 2 000 clientes, muestra de 100 con muestreo sistemático. ¿Cada cuántos eliges? (k)',['20'],[['100','k = N/n = 2000/100.']]),I('Población de 5 000, muestra de 250 sistemática. ¿Cuánto vale k?',['20'],[['250','k = 5000/250.']]),I('Población de 1 200, muestra de 60 sistemática. ¿Cuánto vale k?',['20'],[['60','k = 1200/60.']]),I('Población de 900, muestra de 30 sistemática. ¿Cuánto vale k?',['30'],[['900','k = 900/30.']])]),
    p2:KES.completa([I('Si quieres garantizar que haya hombres y mujeres en la proporción real, usas muestreo ___.',['estratificado'],[['por conveniencia','Para respetar proporciones: estratificado.']]),I('Encuestar solo a los clientes que entran a la tienda un lunes es una muestra por ___.',['conveniencia'],[['estratos','Es por conveniencia.']]),I('Estudiar solo las empresas que siguen abiertas y concluir que «todas tienen éxito» es un sesgo de ___.',['supervivencia'],[['no respuesta','Las que cerraron no aparecen: supervivencia.']])]),
    a1:KES.caso([I('Una app pregunta en redes «¿te gusta nuestro producto?» y el 90 % responde que sí. ¿Qué sesgo es probable?',['respuesta voluntaria','autoseleccion','sesgo de respuesta voluntaria'],[['ninguno','Solo responden los que quieren.']]),I('Un estudio observa que quienes toman café viven más. ¿Puedes concluir que el café causa vivir más? (sí o no)',['no'],[['si','Es observacional: puede haber variables de confusión.']]),I('Una encuesta por teléfono fijo sobre uso de tecnología deja fuera a los jóvenes. ¿Qué sesgo es?',['seleccion','sesgo de seleccion','cobertura','subcobertura'],[['respuesta','La forma de elegir excluye a un grupo: selección.']])]),
    a2:KES.decide([I('Para saber la opinión de los empleados de 4 sucursales con tamaños muy distintos, ¿qué muestreo eliges?',['estratificado','estratificado por sucursal'],[['conveniencia','Estratificado para que todas estén representadas.']]),I('Quieres probar si un nuevo diseño de la app aumenta las compras. ¿Qué haces?',['un experimento','asignar al azar','prueba A/B','experimento aleatorizado'],[['una encuesta','Para causa: experimento con asignación aleatoria (A/B).']]),I('Si el 70 % de los encuestados no contesta, ¿qué haces antes de confiar en los resultados?',['analizar la no respuesta','revisar el sesgo de no respuesta','dar seguimiento a los que no contestaron'],[['nada','Revisar el sesgo de no respuesta.']])])
  }});

/* ---------- Tablas de frecuencia ---------- */
const frecuencias=crearGen({titulo:'Tablas de frecuencia',niveles:NIV,
  explicacion:'La <b>frecuencia absoluta</b> es cuántas veces aparece un valor; la <b>relativa</b> es esa cantidad entre el total (proporción, o × 100 para %); la <b>acumulada</b> suma las anteriores. En una <b>tabla de contingencia</b> (dos variables), el porcentaje condicional divide entre el total de la fila o columna que corresponde.',
  alternativa:'La relativa responde «¿qué parte del total?»; la acumulada, «¿cuántos hasta aquí?». En una tabla de dos variables, primero decide «¿de quiénes?» para saber entre qué total dividir.',
  referencia:'OpenIntro 2.2 – Datos categóricos: tablas de contingencia',regla:'Relativa = frecuencia / total; acumulada = suma hasta esa fila; condicional = celda / total de su fila (o columna).',pista:'¿Entre qué total divides?',
  tarjetas:[['Frecuencia relativa','Frecuencia / total.'],['Frecuencia acumulada','Suma de las frecuencias hasta esa categoría.'],['Porcentaje condicional en una tabla de contingencia','Celda / total de su fila (o columna).']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const f=r.entero(3,40),N=f+r.entero(10,120),v=f/N;return prob({enunciado:`En una encuesta de ${N} personas, ${f} prefieren el té. ¿Cuál es la frecuencia relativa? (4 decimales)`,v,dec:4,
      pasos:[paso('Frecuencia entre total',`${f} / ${N}`,'Parte del total.'),final('Calcula',marca(fmt(v,4)),'Proporción.')],errores:[[f,'Esa es la absoluta.'],[N/f,'Es frecuencia entre total.']],comprobar:()=>cerca(v*N,f)})}},
    b2:{prof:'basico',f:(n,r)=>{const fs=[r.entero(2,15),r.entero(2,15),r.entero(2,15),r.entero(2,15)],k=r.entero(1,3),v=sum(fs.slice(0,k+1));return prob({enunciado:`Frecuencias de las calificaciones 6, 7, 8 y 9: ${lista(fs)}. ¿Cuál es la frecuencia acumulada hasta la calificación ${6+k}?`,v,dec:0,
      pasos:[paso('Suma hasta esa fila',fs.slice(0,k+1).join(' + '),'Acumulada.'),final('Total',marca(v),'Casos hasta ahí.')],errores:[[fs[k],'Esa es solo la de esa fila.'],[sum(fs),'Es hasta esa calificación, no todo.']],comprobar:()=>v===fs.slice(0,k+1).reduce((a,b)=>a+b,0)})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const fs=[r.entero(5,30),r.entero(5,30),r.entero(5,30)],k=r.entero(0,2),N=sum(fs),v=100*fs[k]/N;return prob({enunciado:`Ventas por canal: tienda ${fs[0]}, en línea ${fs[1]}, teléfono ${fs[2]}. ¿Qué porcentaje del total es ${['tienda','en línea','teléfono'][k]}? (2 decimales)`,v,dec:2,unidad:'%',
      pasos:[paso('Total',`${fs.join(' + ')} = ${N}`,'Suma todo.'),final('Porcentaje',`${fs[k]} / ${N} × 100 = ${marca(fmt(v))}`,'%.')],errores:[[fs[k]/N,'Falta × 100.'],[100*fs[k]/fs.reduce((a,b)=>Math.max(a,b)),'Se divide entre el total.']],comprobar:()=>cerca(v*N/100,fs[k])})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const a=r.entero(10,60),b=r.entero(10,60),c=r.entero(10,60),d=r.entero(10,60),v=100*a/(a+b);return prob({enunciado:`Tabla de contingencia: Mujeres — compró ${a}, no compró ${b}; Hombres — compró ${c}, no compró ${d}. ¿Qué porcentaje de las mujeres compró? (2 decimales)`,v,dec:2,unidad:'%',
      pasos:[paso('«De las mujeres»: total de su fila',`${a} + ${b} = ${a+b}`,'Ese es el total que importa.'),final('Porcentaje condicional',`${a} / ${a+b} × 100 = ${marca(fmt(v))}`,'%.')],errores:[[100*a/(a+b+c+d),'Ese es el % del total de personas, no de las mujeres.'],[100*a/(a+c),'Ese es el % de los compradores que son mujeres.']],comprobar:()=>cerca(v*(a+b)/100,a)})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const tot=r.entero(200,800),sat=r.entero(20,80),v=Math.round(tot*sat/100);return prob({enunciado:`En una encuesta a ${tot} clientes, el ${sat} % dijo estar satisfecho. ¿Cuántos clientes es eso? (entero)`,v,dec:0,unidad:'clientes',
      pasos:[paso('Pasa el % a proporción',`${sat} % = ${sat/100}`,'Divide entre 100.'),final('Multiplica por el total',`${tot} × ${sat/100} ≈ ${marca(v)}`,'Frecuencia absoluta.')],errores:[[sat,'Ese es el porcentaje.'],[tot,'Ese es el total.']],comprobar:()=>Math.abs(v-tot*sat/100)<=0.5})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const a=r.entero(20,80),b=r.entero(20,80),c=r.entero(5,40),d=r.entero(5,40),v=100*a/(a+c);return prob({enunciado:`Prueba de una campaña: vieron el anuncio y compraron ${a}, vieron y no compraron ${b}; no lo vieron y compraron ${c}, no lo vieron y no compraron ${d}. De todos los que compraron, ¿qué porcentaje había visto el anuncio? (2 decimales)`,v,dec:2,unidad:'%',
      pasos:[paso('«De los que compraron»: total de la columna',`${a} + ${c} = ${a+c}`,'Los compradores.'),final('Porcentaje',`${a} / ${a+c} × 100 = ${marca(fmt(v))}`,'Condicional por columna.')],errores:[[100*a/(a+b),'Ese es el % de los que vieron el anuncio que compraron.'],[100*a/(a+b+c+d),'Ese es sobre el total.']],comprobar:()=>cerca(v*(a+c)/100,a)})}}
  }});

/* ---------- Histogramas y forma ---------- */
const histogramas=crearGen({titulo:'Histogramas y forma de la distribución',niveles:NIV,
  explicacion:'Un <b>histograma</b> agrupa una variable numérica en intervalos (clases) del mismo ancho: ancho ≈ (máximo − mínimo) / número de clases. La forma puede ser <b>simétrica</b> (media ≈ mediana), <b>sesgada a la derecha</b> (cola larga hacia valores altos: media > mediana, como los ingresos) o <b>a la izquierda</b> (media < mediana). También puede ser unimodal o bimodal y tener <b>valores atípicos</b>.',
  alternativa:'La cola es como la cola de un cometa: si la cola apunta a la derecha (valores altos), el sesgo es a la derecha, y la media se va hacia la cola.',
  referencia:'OpenIntro 2.1 – Histogramas y forma',regla:'Ancho de clase = rango / número de clases. Sesgo a la derecha: media > mediana; a la izquierda: media < mediana; simétrica: media ≈ mediana.',pista:'¿Hacia dónde está la cola?',
  tarjetas:[['Sesgo a la derecha','Cola hacia valores altos; la media es mayor que la mediana.'],['Ancho de clase','(máximo − mínimo) / número de clases.'],['Distribución bimodal','Tiene dos picos (puede mezclar dos grupos).']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const mn=r.entero(0,50),k=r.elegir([4,5,8,10]),w=r.entero(2,20),mx=mn+k*w;return prob({enunciado:`Los datos van de ${mn} a ${mx} y quieres ${k} clases del mismo ancho. ¿Qué ancho tiene cada clase?`,v:w,dec:2,
      pasos:[paso('Rango',`${mx} − ${mn} = ${mx-mn}`,'Máximo − mínimo.'),final('Entre el número de clases',`${mx-mn} / ${k} = ${marca(w)}`,'Ancho.')],errores:[[mx-mn,'Divide entre el número de clases.'],[(mx-mn)*k,'Se divide, no se multiplica.']],comprobar:()=>mn+k*w===mx})}},
    b2:{prof:'basico',f:(n,r)=>{const [forma,me,md]=r.elegir([['derecha',r.entero(60,90),r.entero(30,55)],['izquierda',r.entero(30,55),r.entero(60,90)]]),v=forma==='derecha'?1:0;return prob({enunciado:`En un histograma la media es ${me} y la mediana es ${md}. Escribe 1 si el sesgo es a la derecha y 0 si es a la izquierda.`,v,dec:0,
      pasos:[paso('Compara media y mediana',`media ${me>md?'>':'<'} mediana`,'La media se va hacia la cola.'),final('Sesgo',marca(v),forma==='derecha'?'Cola a la derecha.':'Cola a la izquierda.')],errores:[[1-v,'La media se va hacia la cola larga.']],comprobar:()=>(me>md)===(v===1)})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const w=r.elegir([5,10,20]),mn=r.entero(0,5)*w,x=mn+r.entero(0,40),cl=Math.floor((x-mn)/w)+1;return prob({enunciado:`Clases de ancho ${w} empezando en ${mn} ([${mn}, ${mn+w}), [${mn+w}, ${mn+2*w}), …). ¿En qué número de clase cae el valor ${x}?`,v:cl,dec:0,
      pasos:[paso('Distancia al inicio',`(${x} − ${mn}) / ${w} = ${fmt((x-mn)/w,2)}`,'Cuántos anchos caben.'),final('Parte entera + 1',marca(cl),'Las clases se cuentan desde 1.')],errores:[[cl-1,'Las clases se cuentan desde 1.'],[cl+1,'Revisa el límite superior abierto.']],comprobar:()=>x>=mn+(cl-1)*w&&x<mn+cl*w})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const a=Array.from({length:7},()=>r.entero(10,40)),at=r.entero(150,400),b=[...a,at],m1=media(a),m2=media(b),v=m2-m1;return prob({enunciado:`Siete datos: ${lista(a)}. Se agrega un valor atípico de ${at}. ¿Cuánto aumenta la media? (2 decimales)`,v,dec:2,
      pasos:[paso('Media sin el atípico',`${sum(a)} / 7 = ${fmt(m1)}`,'Antes.'),paso('Media con el atípico',`${sum(b)} / 8 = ${fmt(m2)}`,'Después.'),final('Diferencia',marca(fmt(v)),'La media es sensible a los atípicos.')],errores:[[at,'Esa es el valor, no el cambio en la media.'],[m2,'Esa es la nueva media.']],comprobar:()=>cerca(v,(at-m1)/8)})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const md=r.entero(8,15)*1000,me=md+r.entero(2,9)*1000;return prob({enunciado:`Los sueldos de una empresa tienen mediana $${md} y media $${me}. Escribe 1 si la distribución tiene sesgo a la derecha (pocos sueldos muy altos) o 0 si no.`,v:1,dec:0,
      pasos:[paso('Media vs mediana',`${me} > ${md}`,'La media se jala hacia los sueldos altos.'),final('Conclusión',marca(1),'Sesgo a la derecha.')],errores:[[0,'Media mayor que mediana indica cola a la derecha.']],comprobar:()=>me>md})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const mn=r.entero(10,30),mx=mn+r.entero(30,120),k=r.elegir([5,6,8]),v=(mx-mn)/k;return prob({enunciado:`Los tiempos de entrega van de ${mn} a ${mx} minutos. Para un histograma con ${k} clases, ¿de cuántos minutos es cada clase? (2 decimales)`,v,dec:2,unidad:'min',
      pasos:[paso('Rango',`${mx} − ${mn} = ${mx-mn}`,'Del más rápido al más lento.'),final('Entre las clases',`${mx-mn} / ${k} = ${marca(fmt(v))}`,'Ancho.')],errores:[[mx-mn,'Falta dividir entre las clases.'],[mx/k,'Usa el rango, no solo el máximo.']],comprobar:()=>cerca(mn+k*v,mx)})}}
  }});

/* ---------- Correlación ---------- */
const corr=(x,y)=>{const mx=media(x),my=media(y),sxy=sum(x.map((v,i)=>(v-mx)*(y[i]-my))),sx=Math.sqrt(sum(x.map(v=>(v-mx)**2))),sy=Math.sqrt(sum(y.map(v=>(v-my)**2)));return sxy/(sx*sy)};
const corrAlt=(x,y)=>{const n=x.length,sx=sum(x),sy=sum(y),sxy=sum(x.map((v,i)=>v*y[i])),sxx=sum(x.map(v=>v*v)),syy=sum(y.map(v=>v*v));return (n*sxy-sx*sy)/Math.sqrt((n*sxx-sx*sx)*(n*syy-sy*sy))};
const datosR=(r,signo)=>{for(;;){const x=Array.from({length:5},()=>r.entero(1,20)),y=x.map(v=>Math.round(signo*v*r.entero(1,3)+r.entero(-6,6)+30));if(new Set(x).size>2&&new Set(y).size>2)return [x,y]}};
const correlacion=crearGen({titulo:'Correlación',niveles:NIV,
  explicacion:'El coeficiente de correlación <b>r</b> (de −1 a 1) mide qué tan fuerte es la relación <b>lineal</b> entre dos variables numéricas: cerca de 1, positiva fuerte; cerca de −1, negativa fuerte; cerca de 0, sin relación lineal. <b>r²</b> es la proporción de la variación de y explicada por x. <b>Correlación no implica causalidad</b>: puede haber una tercera variable que mueva a las dos.',
  alternativa:'r es como la «disciplina» de los puntos: si forman una recta casi perfecta que sube, r ≈ 1; si bajan, r ≈ −1; si están revueltos, r ≈ 0.',
  referencia:'OpenIntro 8.1 – Correlación (r)',regla:'r = Σ(x − x̄)(y − ȳ) / √(Σ(x − x̄)² · Σ(y − ȳ)²); −1 ≤ r ≤ 1; r² = proporción explicada; correlación ≠ causalidad.',pista:'¿Sube, baja o no hay patrón?',
  tarjetas:[['Rango de r','De −1 a 1.'],['r = −0.9','Relación lineal negativa fuerte.'],['r²','Proporción de la variación de y que explica x.'],['¿Correlación implica causa?','No.']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const v=+(r.entero(-95,95)/100).toFixed(2),fuerte=Math.abs(v)>=0.7?1:0;return prob({enunciado:`Un estudio reporta r = ${v}. Escribe 1 si la relación lineal es fuerte (|r| ≥ 0.7) o 0 si no.`,v:fuerte,dec:0,
      pasos:[paso('Valor absoluto',`|${v}| = ${Math.abs(v)}`,'El signo es la dirección; el tamaño, la fuerza.'),final('Compara con 0.7',marca(fuerte),fuerte?'Fuerte.':'No es fuerte.')],errores:[[1-fuerte,'Mira el valor absoluto.']],comprobar:()=>(Math.abs(v)>=0.7)===(fuerte===1)})}},
    b2:{prof:'basico',f:(n,r)=>{const v=r.entero(-9,9)/10||0.5,v2=+(v*v).toFixed(4);return prob({enunciado:`Si r = ${v}, ¿cuánto vale r²? (4 decimales)`,v:v2,dec:4,
      pasos:[paso('Eleva al cuadrado',`(${v})²`,'Siempre positivo.'),final('r²',marca(fmt(v2,4)),'Proporción explicada.')],errores:[[Math.abs(v),'Falta elevar al cuadrado.'],[2*v,'Es al cuadrado, no por 2.']],comprobar:()=>cerca(Math.sqrt(v2),Math.abs(v))})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const [x,y]=datosR(r,r.prob(.5)?1:-1),v=corr(x,y);return prob({enunciado:`Calcula r para x = (${lista(x)}) y y = (${lista(y)}). (2 decimales)`,v,dec:2,tol:0.006,
      pasos:[paso('Medias',`x̄ = ${fmt(media(x))}, ȳ = ${fmt(media(y))}`,'Centro de cada variable.'),paso('Productos de desviaciones','Σ(x − x̄)(y − ȳ)','Numerador.'),final('Divide entre √(Σ(x − x̄)² Σ(y − ȳ)²)',marca(fmt(v)),'Entre −1 y 1.')],errores:[[-v,'Revisa el signo: ¿sube o baja?'],[v*v,'Eso es r².']],comprobar:()=>cerca(v,corrAlt(x,y),1e-9)})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const v=r.entero(-9,9)/10||0.6,v2=v*v,pct=100*v2;return prob({enunciado:`Con r = ${v} entre horas de estudio y calificación, ¿qué porcentaje de la variación de la calificación explican las horas? (2 decimales)`,v:pct,dec:2,unidad:'%',
      pasos:[paso('r²',`(${v})² = ${fmt(v2,4)}`,'Proporción explicada.'),final('A porcentaje',`× 100 = ${marca(fmt(pct))}`,'%.')],errores:[[100*Math.abs(v),'Se usa r², no r.'],[v2,'Falta × 100.']],comprobar:()=>cerca(Math.sqrt(pct/100),Math.abs(v))})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const [x,y]=datosR(r,1),v=corr(x,y);return prob({enunciado:`Gasto en publicidad (miles) por mes: (${lista(x)}); ventas (miles): (${lista(y)}). ¿Cuál es r? (2 decimales)`,v,dec:2,tol:0.006,
      pasos:[paso('Medias y desviaciones',`x̄ = ${fmt(media(x))}, ȳ = ${fmt(media(y))}`,'Primero los centros.'),final('r',marca(fmt(v)),v>0?'Positiva: más publicidad, más ventas (no prueba causa).':'Negativa.')],errores:[[-v,'Revisa el signo.'],[v*v,'Eso es r².']],comprobar:()=>cerca(v,corrAlt(x,y),1e-9)})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const v=+(r.entero(70,95)/100).toFixed(2);return prob({enunciado:`En verano suben a la vez las ventas de helado y los ahogamientos (r = ${v}). Escribe 1 si eso prueba que el helado causa ahogamientos, o 0 si no.`,v:0,dec:0,
      pasos:[paso('¿Hay una tercera variable?','El calor (verano)','Aumenta las dos.'),final('Conclusión',marca(0),'Correlación no implica causalidad.')],errores:[[1,'Una variable de confusión (el calor) explica las dos.']],comprobar:()=>v>0})}}
  }});

/* ---------- Conteo ---------- */
const conteo=crearGen({titulo:'Conteo: permutaciones y combinaciones',niveles:NIV,
  explicacion:'<b>Principio multiplicativo</b>: si hay a opciones y luego b, hay a × b. <b>Permutaciones</b> (importa el orden): nPr = n! / (n − r)!. <b>Combinaciones</b> (no importa el orden): nCr = n! / (r! (n − r)!). n! = n × (n − 1) × … × 1, y 0! = 1.',
  alternativa:'¿Importa quién queda primero? Podio de carrera (oro, plata, bronce): sí → permutación. Elegir 3 amigos para un viaje: no → combinación.',
  referencia:'OpenIntro 3.4 (y apéndice) – Conteo',regla:'Multiplicativo: a × b. Orden importa: nPr = n!/(n − r)!. Orden no importa: nCr = n!/(r!(n − r)!).',pista:'¿Importa el orden?',
  tarjetas:[['Permutación','Importa el orden: nPr = n!/(n − r)!.'],['Combinación','No importa el orden: nCr = n!/(r!(n − r)!).'],['0!','1.']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const k=r.entero(3,7),v=fact(k);return prob({enunciado:`¿Cuánto vale ${k}!?`,v,dec:0,pasos:[paso('Multiplica hacia abajo',Array.from({length:k},(_,i)=>k-i).join(' × '),'Hasta 1.'),final('Resultado',marca(v),'Factorial.')],errores:[[k*(k-1),'Faltan factores.'],[sum(Array.from({length:k},(_,i)=>i+1)),'Es producto, no suma.']],comprobar:()=>v===Array.from({length:k},(_,i)=>i+1).reduce((a,b)=>a*b,1)})}},
    b2:{prof:'basico',f:(n,r)=>{const a=r.entero(2,6),b=r.entero(2,6),c=r.entero(2,4),v=a*b*c;return prob({enunciado:`Un menú tiene ${a} entradas, ${b} platos fuertes y ${c} postres. ¿Cuántas comidas distintas puedes armar?`,v,dec:0,
      pasos:[paso('Principio multiplicativo',`${a} × ${b} × ${c}`,'Una de cada.'),final('Total',marca(v),'Combinaciones de menú.')],errores:[[a+b+c,'Se multiplica.'],[a*b,'Faltan los postres.']],comprobar:()=>v===a*b*c})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const N=r.entero(5,10),k=r.entero(2,3),v=Pm(N,k);return prob({enunciado:`${N} corredores compiten. ¿De cuántas formas se pueden repartir oro, plata y ${k===3?'bronce':'(solo oro y plata)'}? (${N}P${k})`,v,dec:0,
      pasos:[paso('Importa el orden','nPr = n!/(n − r)!','Oro ≠ plata.'),final('Calcula',`${N}!/${N-k}! = ${marca(v)}`,'Permutaciones.')],errores:[[C(N,k),'Esa es la combinación: aquí sí importa el orden.'],[N**k,'Sin repetición: no es n^r.']],comprobar:()=>v===Array.from({length:k},(_,i)=>N-i).reduce((a,b)=>a*b,1)})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const N=r.entero(6,12),k=r.entero(2,4),v=C(N,k);return prob({enunciado:`¿De cuántas formas eliges ${k} personas de ${N} para un comité (sin cargos)? (${N}C${k})`,v,dec:0,
      pasos:[paso('No importa el orden','nCr = n!/(r!(n − r)!)','Comité sin cargos.'),final('Calcula',`${N}!/(${k}!·${N-k}!) = ${marca(v)}`,'Combinaciones.')],errores:[[Pm(N,k),'Esa es la permutación: aquí no importa el orden.'],[N*k,'Usa la fórmula de combinaciones.']],comprobar:()=>v===C(N-1,k-1)+C(N-1,k)})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const d=r.elegir([4,6]),v=10**d;return prob({enunciado:`Un PIN tiene ${d} dígitos (0–9) y se pueden repetir. ¿Cuántos PIN distintos hay?`,v,dec:0,
      pasos:[paso('Cada posición: 10 opciones',`10 × … × 10 (${d} veces)`,'Con repetición.'),final('Total',`10^${d} = ${marca(v)}`,'Combinaciones posibles.')],errores:[[10*d,'Se multiplica 10 por sí mismo.'],[Pm(10,d),'Se pueden repetir los dígitos.']],comprobar:()=>v===Math.pow(10,d)})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const N=r.elegir([40,45,49,56]),k=6,v=C(N,k);return prob({enunciado:`Una lotería elige ${k} números distintos de ${N} sin importar el orden. ¿Cuántas combinaciones hay?`,v,dec:0,
      pasos:[paso('Sin orden y sin repetición',`${N}C${k}`,'Combinación.'),final('Calcula',marca(v),'Por eso es tan difícil ganar.')],errores:[[Pm(N,k),'El orden no importa.'],[N**k,'Sin repetición.']],comprobar:()=>{let p=1;for(let i=0;i<k;i++)p=p*(N-i)/(i+1);return cerca(p,v)}})}}
  }});

/* ---------- Teorema de Bayes ---------- */
const bayes=crearGen({titulo:'Teorema de Bayes',niveles:NIV,
  explicacion:'Bayes invierte una condicional: P(A|B) = P(B|A)·P(A) / P(B), con P(B) = P(B|A)P(A) + P(B|no A)P(no A). Ejemplo clásico: una prueba médica muy buena para una enfermedad rara da muchos <b>falsos positivos</b>, porque la prevalencia (P(A)) es pequeña. Un árbol o una tabla con 10 000 personas imaginarias ayuda mucho.',
  alternativa:'Imagina 10 000 personas: cuántas están enfermas (prevalencia), cuántas de ellas dan positivo (sensibilidad) y cuántas sanas dan positivo por error. P(enfermo | positivo) = enfermos positivos / todos los positivos.',
  referencia:'OpenIntro 3.2 – Teorema de Bayes',regla:'P(A|B) = P(B|A)P(A) / [P(B|A)P(A) + P(B|¬A)P(¬A)].',pista:'Calcula primero P(B) total.',
  tarjetas:[['Teorema de Bayes','P(A|B) = P(B|A)P(A) / P(B).'],['Prevalencia','Proporción de la población que tiene la condición: P(A).'],['Por qué una prueba buena da falsos positivos','Si la condición es rara, los positivos falsos de los sanos pesan mucho.']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const pBA=r.entero(5,9)/10,pA=r.entero(1,5)/10,pB=+(pBA*pA+r.entero(1,4)/10*(1-pA)).toFixed(4),v=pBA*pA/pB;return prob({enunciado:`P(B|A) = ${pBA}, P(A) = ${pA} y P(B) = ${pB}. ¿Cuánto vale P(A|B)? (4 decimales)`,v,dec:4,
      pasos:[paso('Bayes',`${pBA} × ${pA} / ${pB}`,'Fórmula directa.'),final('Calcula',marca(fmt(v,4)),'Probabilidad invertida.')],errores:[[pBA,'Esa es P(B|A), no P(A|B).'],[pBA*pA,'Falta dividir entre P(B).']],comprobar:()=>cerca(v*pB,pBA*pA)})}},
    b2:{prof:'basico',f:(n,r)=>{const pBA=r.entero(6,9)/10,pA=r.entero(1,4)/10,pBno=r.entero(1,3)/10,v=pBA*pA+pBno*(1-pA);return prob({enunciado:`P(A) = ${pA}, P(B|A) = ${pBA} y P(B|no A) = ${pBno}. ¿Cuánto vale P(B) total? (4 decimales)`,v,dec:4,
      pasos:[paso('Probabilidad total',`${pBA}×${pA} + ${pBno}×${fmt(1-pA,2)}`,'Por los dos caminos.'),final('Suma',marca(fmt(v,4)),'P(B).')],errores:[[pBA*pA,'Falta el camino de «no A».'],[pBA+pBno,'Hay que ponderar por P(A) y P(no A).']],comprobar:()=>cerca(v,pA*pBA+(1-pA)*pBno)})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const prev=r.elegir([0.01,0.02,0.05,0.1]),sens=r.elegir([0.9,0.95,0.99]),fp=r.elegir([0.05,0.1,0.02]),pB=sens*prev+fp*(1-prev),v=sens*prev/pB;return prob({enunciado:`Una enfermedad afecta al ${prev*100} % de la población. La prueba detecta al ${sens*100} % de los enfermos y da positivo al ${fp*100} % de los sanos. Si alguien da positivo, ¿qué probabilidad hay de que esté enfermo? (4 decimales)`,v,dec:4,
      pasos:[paso('P(positivo)',`${sens}×${prev} + ${fp}×${fmt(1-prev,2)} = ${fmt(pB,4)}`,'Enfermos y sanos que dan positivo.'),final('Bayes',`${sens}×${prev} / ${fmt(pB,4)} = ${marca(fmt(v,4))}`,'P(enfermo | positivo).')],errores:[[sens,'Esa es la sensibilidad, no P(enfermo | positivo).'],[sens*prev,'Falta dividir entre P(positivo).']],comprobar:()=>{const N=1e6,e=N*prev,tp=e*sens,fpos=(N-e)*fp;return cerca(v,tp/(tp+fpos))}})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const p1=r.entero(3,7)/10,d1=r.entero(1,5)/100,d2=r.entero(1,5)/100,pD=p1*d1+(1-p1)*d2,v=p1*d1/pD;return prob({enunciado:`La máquina A hace el ${p1*100} % de las piezas y el ${d1*100} % le salen defectuosas; la máquina B hace el resto y le sale defectuoso el ${d2*100} %. Una pieza es defectuosa: ¿qué probabilidad hay de que sea de A? (4 decimales)`,v,dec:4,
      pasos:[paso('P(defectuosa)',`${p1}×${d1} + ${fmt(1-p1,2)}×${d2} = ${fmt(pD,4)}`,'Por las dos máquinas.'),final('Bayes',`${p1}×${d1} / ${fmt(pD,4)} = ${marca(fmt(v,4))}`,'P(A | defectuosa).')],errores:[[p1,'Esa es P(A) sin la información de que es defectuosa.'],[d1,'Esa es P(defectuosa | A).']],comprobar:()=>cerca(v,1/(1+((1-p1)*d2)/(p1*d1)))})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const spam=r.elegir([0.3,0.4,0.5]),pw=r.elegir([0.6,0.7,0.8]),pwno=r.elegir([0.05,0.1]),pW=pw*spam+pwno*(1-spam),v=pw*spam/pW;return prob({enunciado:`El ${spam*100} % de los correos es spam. La palabra «gratis» aparece en el ${pw*100} % del spam y en el ${pwno*100} % del correo normal. Si un correo tiene «gratis», ¿qué probabilidad hay de que sea spam? (4 decimales)`,v,dec:4,
      pasos:[paso('P(«gratis»)',`${pw}×${spam} + ${pwno}×${fmt(1-spam,2)} = ${fmt(pW,4)}`,'Spam y normal.'),final('Bayes',marca(fmt(v,4)),'Así funcionan los filtros bayesianos.')],errores:[[pw,'Esa es P(«gratis» | spam).'],[spam,'Esa es la probabilidad previa.']],comprobar:()=>cerca(v*pW,pw*spam)})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const prev=r.elegir([0.001,0.002,0.005]),sens=0.99,fp=r.elegir([0.01,0.02]),pB=sens*prev+fp*(1-prev),v=sens*prev/pB;return prob({enunciado:`Una alerta de fraude detecta el 99 % de los fraudes y marca por error el ${fp*100} % de las compras legítimas. Solo el ${prev*100} % de las compras es fraude. Si una compra se marca, ¿qué probabilidad hay de que sea fraude? (4 decimales)`,v,dec:4,
      pasos:[paso('P(marcada)',`0.99×${prev} + ${fp}×${fmt(1-prev,3)} = ${fmt(pB,5)}`,'Fraudes y legítimas marcadas.'),final('Bayes',marca(fmt(v,4)),'Baja: la mayoría de las alertas son falsos positivos.')],errores:[[0.99,'Esa es la sensibilidad.'],[prev,'Esa es la prevalencia.']],comprobar:()=>{const N=1e7,f=N*prev,tp=f*sens,fpos=(N-f)*fp;return cerca(v,tp/(tp+fpos))}})}}
  }});

/* ---------- Variables aleatorias ---------- */
const distrib=r=>{const xs=[0,1,2,3],w=xs.map(()=>r.entero(1,6)),t=sum(w);return {xs,ps:w.map(x=>x/t),txt:xs.map((x,i)=>`P(X=${x}) = ${w[i]}/${t}`).join(', ')}};
const va=crearGen({titulo:'Variables aleatorias, esperanza y varianza',niveles:NIV,
  explicacion:'Una variable aleatoria discreta asigna probabilidades a valores (que suman 1). Su <b>esperanza</b> (media) es E[X] = Σ x·P(x); su <b>varianza</b>, Var(X) = Σ (x − E[X])²·P(x) = E[X²] − E[X]², y la desviación estándar es su raíz. Propiedades: E[aX + b] = aE[X] + b; Var(aX + b) = a²Var(X).',
  alternativa:'La esperanza es el promedio a la larga: si juegas muchísimas veces, ¿cuánto ganas en promedio por juego?',
  referencia:'OpenIntro 3.4 – Variables aleatorias',regla:'E[X] = Σx·P(x); Var(X) = Σ(x − μ)²P(x); E[aX + b] = aE[X] + b; Var(aX + b) = a²Var(X).',pista:'Multiplica cada valor por su probabilidad.',
  tarjetas:[['Esperanza de X','E[X] = Σ x·P(x).'],['Varianza de X','Σ (x − μ)²·P(x) = E[X²] − μ².'],['E[aX + b]','aE[X] + b.'],['Var(aX + b)','a²Var(X).']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const d=distrib(r),v=sum(d.xs.map((x,i)=>x*d.ps[i]));return prob({enunciado:`X toma 0, 1, 2 o 3 con ${d.txt}. ¿Cuánto vale E[X]? (4 decimales)`,v,dec:4,
      pasos:[paso('Σ x·P(x)',d.xs.map((x,i)=>`${x}×${fmt(d.ps[i],3)}`).join(' + '),'Pondera cada valor.'),final('Suma',marca(fmt(v,4)),'Esperanza.')],errores:[[1.5,'No es el promedio simple de 0 a 3.'],[sum(d.ps),'Las probabilidades suman 1.']],comprobar:()=>cerca(v,d.ps[1]+2*d.ps[2]+3*d.ps[3])})}},
    b2:{prof:'basico',f:(n,r)=>{const E=r.entero(2,20),a=r.entero(2,5),b=r.entero(-10,10),v=a*E+b;return prob({enunciado:`Si E[X] = ${E}, ¿cuánto vale E[${a}X ${b<0?'−':'+'} ${Math.abs(b)}]?`,v,dec:2,
      pasos:[paso('Linealidad','E[aX + b] = aE[X] + b','Propiedad.'),final('Sustituye',`${a}×${E} ${b<0?'−':'+'} ${Math.abs(b)} = ${marca(v)}`,'Resultado.')],errores:[[a*E,'Falta sumar b.'],[E+b,'Falta multiplicar por a.']],comprobar:()=>v===a*E+b})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const d=distrib(r),mu=sum(d.xs.map((x,i)=>x*d.ps[i])),v=sum(d.xs.map((x,i)=>(x-mu)**2*d.ps[i]));return prob({enunciado:`X toma 0, 1, 2 o 3 con ${d.txt}. ¿Cuánto vale Var(X)? (4 decimales)`,v,dec:4,
      pasos:[paso('Media',`μ = ${fmt(mu,4)}`,'Primero E[X].'),final('Σ (x − μ)²P(x)',marca(fmt(v,4)),'Varianza.')],errores:[[mu,'Esa es la media.'],[Math.sqrt(v),'Esa es la desviación estándar.']],comprobar:()=>cerca(v,sum(d.xs.map((x,i)=>x*x*d.ps[i]))-mu*mu)})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const V=r.entero(2,20),a=r.entero(2,5),b=r.entero(1,10),v=a*a*V;return prob({enunciado:`Si Var(X) = ${V}, ¿cuánto vale Var(${a}X + ${b})?`,v,dec:2,
      pasos:[paso('Propiedad','Var(aX + b) = a²Var(X)','La constante b no cambia la dispersión.'),final('Calcula',`${a}²×${V} = ${marca(v)}`,'Resultado.')],errores:[[a*V,'Es a², no a.'],[a*a*V+b,'b no afecta la varianza.']],comprobar:()=>v===a*a*V})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const premio=r.entero(5,50)*10,p=r.elegir([0.01,0.02,0.05]),costo=r.entero(2,10),v=premio*p-costo;return prob({enunciado:`Un juego cuesta $${costo}. Ganas $${premio} con probabilidad ${p}; si no, nada. ¿Cuál es tu ganancia esperada por juego? (2 decimales; negativo = pierdes)`,v,dec:2,unidad:'pesos',
      pasos:[paso('Lo que esperas ganar',`${premio} × ${p} = ${fmt(premio*p)}`,'Premio por probabilidad.'),final('Menos el costo',`${fmt(premio*p)} − ${costo} = ${marca(fmt(v))}`,'Ganancia esperada.')],errores:[[premio*p,'Falta restar el costo.'],[premio-costo,'Hay que ponderar por la probabilidad.']],comprobar:()=>cerca(v,p*(premio-costo)+(1-p)*(-costo))})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const prima=r.entero(20,60)*100,pago=r.entero(5,20)*10000,p=r.elegir([0.01,0.02,0.03]),v=prima-pago*p;return prob({enunciado:`Una aseguradora cobra $${prima} al año. Con probabilidad ${p} paga un siniestro de $${pago}. ¿Cuál es su ganancia esperada por póliza? (2 decimales)`,v,dec:2,unidad:'pesos',
      pasos:[paso('Pago esperado',`${pago} × ${p} = ${fmt(pago*p)}`,'Siniestro por probabilidad.'),final('Prima menos pago esperado',`${prima} − ${fmt(pago*p)} = ${marca(fmt(v))}`,'Por póliza.')],errores:[[prima,'Falta restar el pago esperado.'],[prima-pago,'Se pondera por la probabilidad.']],comprobar:()=>cerca(v,(1-p)*prima+p*(prima-pago))})}}
  }});

/* ---------- Binomial ---------- */
const binom=(n,k,p)=>C(n,k)*p**k*(1-p)**(n-k);
const binomial=crearGen({titulo:'Distribución binomial',niveles:NIV,
  explicacion:'X ~ Binomial(n, p) cuenta éxitos en <b>n</b> ensayos independientes con la misma probabilidad <b>p</b> de éxito. P(X = k) = C(n, k)·p^k·(1 − p)^(n − k). Media: np; varianza: np(1 − p). «Al menos uno» se calcula como 1 − P(X = 0).',
  alternativa:'Lanzar una moneda trucada n veces y contar caras: C(n, k) cuenta de cuántas formas salen k caras y p^k(1 − p)^(n − k) es la probabilidad de cada forma.',
  referencia:'OpenIntro 4.3 – Distribución binomial',regla:'P(X = k) = C(n, k)p^k(1 − p)^(n − k); μ = np; σ² = np(1 − p); P(al menos 1) = 1 − (1 − p)^n.',pista:'Identifica n, p y k.',
  tarjetas:[['Condiciones de la binomial','n ensayos independientes, dos resultados y la misma p.'],['Media de la binomial','np.'],['P(al menos un éxito)','1 − (1 − p)^n.']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const N=r.entero(10,200),p=r.entero(1,9)/10,v=N*p;return prob({enunciado:`X ~ Binomial(n = ${N}, p = ${p}). ¿Cuál es la media?`,v,dec:2,pasos:[paso('μ = np',`${N} × ${p}`,'Media.'),final('Calcula',marca(fmt(v)),'Éxitos esperados.')],errores:[[N*p*(1-p),'Esa es la varianza.'],[p,'Esa es la probabilidad.']],comprobar:()=>cerca(v/N,p)})}},
    b2:{prof:'basico',f:(n,r)=>{const N=r.entero(10,100),p=r.entero(1,9)/10,v=N*p*(1-p);return prob({enunciado:`X ~ Binomial(n = ${N}, p = ${p}). ¿Cuál es la varianza? (2 decimales)`,v,dec:2,pasos:[paso('σ² = np(1 − p)',`${N} × ${p} × ${fmt(1-p,1)}`,'Varianza.'),final('Calcula',marca(fmt(v)),'Dispersión.')],errores:[[N*p,'Esa es la media.'],[Math.sqrt(v),'Esa es la desviación estándar.']],comprobar:()=>cerca(v,N*p-N*p*p)})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const N=r.entero(4,10),k=r.entero(0,N),p=r.entero(1,9)/10,v=binom(N,k,p);return prob({enunciado:`X ~ Binomial(n = ${N}, p = ${p}). ¿Cuánto vale P(X = ${k})? (4 decimales)`,v,dec:4,
      pasos:[paso('C(n, k)',`C(${N}, ${k}) = ${C(N,k)}`,'Formas de obtener k éxitos.'),final('× p^k (1 − p)^(n − k)',`${C(N,k)} × ${p}^${k} × ${fmt(1-p,1)}^${N-k} = ${marca(fmt(v,4))}`,'Probabilidad.')],errores:[[p**k*(1-p)**(N-k),'Falta C(n, k).'],[C(N,k)*p**k,'Falta (1 − p)^(n − k).']],comprobar:()=>cerca(sum(Array.from({length:N+1},(_,i)=>binom(N,i,p))),1)&&cerca(v,binom(N,k,p))})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const N=r.entero(3,10),p=r.entero(1,5)/10,v=1-(1-p)**N;return prob({enunciado:`X ~ Binomial(n = ${N}, p = ${p}). ¿Cuánto vale P(X ≥ 1)? (4 decimales)`,v,dec:4,
      pasos:[paso('Complemento','1 − P(X = 0)','Más fácil que sumar todo.'),final('P(X = 0) = (1 − p)^n',`1 − ${fmt(1-p,1)}^${N} = ${marca(fmt(v,4))}`,'Al menos uno.')],errores:[[N*p,'Eso es la media, no una probabilidad.'],[(1-p)**N,'Esa es P(X = 0).']],comprobar:()=>cerca(v,sum(Array.from({length:N},(_,i)=>binom(N,i+1,p))))})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const N=r.entero(5,12),k=r.entero(0,3),p=r.elegir([0.02,0.05,0.1]),v=binom(N,k,p);return prob({enunciado:`El ${p*100} % de las piezas sale defectuoso. En un lote de ${N}, ¿qué probabilidad hay de exactamente ${k} defectuosas? (4 decimales)`,v,dec:4,
      pasos:[paso('Binomial',`n = ${N}, p = ${p}, k = ${k}`,'Piezas independientes.'),final('P(X = k)',marca(fmt(v,4)),'Probabilidad.')],errores:[[p**k,'Falta el resto de la fórmula.'],[N*p,'Esa es la media.']],comprobar:()=>cerca(v,binom(N,k,p))})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const N=r.entero(5,20),p=r.elegir([0.1,0.2,0.3]),v=1-(1-p)**N;return prob({enunciado:`Un vendedor cierra una venta en el ${p*100} % de sus llamadas. Si hace ${N} llamadas, ¿qué probabilidad hay de cerrar al menos una? (4 decimales)`,v,dec:4,
      pasos:[paso('Complemento','1 − P(ninguna)','Al menos una.'),final('P(ninguna) = (1 − p)^n',`1 − ${fmt(1-p,1)}^${N} = ${marca(fmt(v,4))}`,'Probabilidad.')],errores:[[N*p,'Eso es el número esperado de ventas.'],[(1-p)**N,'Esa es la de no cerrar ninguna.']],comprobar:()=>cerca(v,1-binom(N,0,p))})}}
  }});

/* ---------- Poisson ---------- */
const pois=(l,k)=>Math.exp(-l)*l**k/fact(k);
const poisson=crearGen({titulo:'Distribución de Poisson',niveles:NIV,
  explicacion:'X ~ Poisson(λ) cuenta eventos en un intervalo (llamadas por hora, errores por página) cuando ocurren independientes a una tasa promedio <b>λ</b>. P(X = k) = e^(−λ)·λ^k / k!. Su media y su varianza valen λ. Si la tasa es por otro intervalo, ajústala: 3 por hora → 6 en 2 horas.',
  alternativa:'Piensa en clientes que llegan a una caja: en promedio llegan λ por minuto, pero cada minuto puede variar; Poisson dice qué tan probable es cada cantidad.',
  referencia:'OpenIntro 4.5 – Distribución de Poisson',regla:'P(X = k) = e^(−λ)λ^k/k!; media = varianza = λ; ajusta λ al intervalo.',pista:'¿Cuál es λ para ese intervalo?',
  tarjetas:[['Fórmula de Poisson','P(X = k) = e^(−λ)λ^k / k!.'],['Media y varianza de Poisson','Ambas valen λ.'],['Cambiar de intervalo','λ se escala: 3 por hora → 6 en 2 horas.']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const l=r.entero(1,12);return prob({enunciado:`X ~ Poisson(λ = ${l}). ¿Cuál es su varianza?`,v:l,dec:2,pasos:[paso('En Poisson','media = varianza = λ','Propiedad.'),final('Varianza',marca(l),'λ.')],errores:[[l*l,'No es λ².'],[Math.sqrt(l),'Esa sería la desviación estándar.']],comprobar:()=>l>0})}},
    b2:{prof:'basico',f:(n,r)=>{const l=r.entero(1,8),h=r.entero(2,5),v=l*h;return prob({enunciado:`Llegan en promedio ${l} clientes por hora. ¿Cuál es λ para un periodo de ${h} horas?`,v,dec:2,pasos:[paso('Escala la tasa',`${l} × ${h}`,'Mismo proceso, más tiempo.'),final('λ',marca(v),'Para el nuevo intervalo.')],errores:[[l,'Hay que ajustarla al intervalo.'],[l/h,'Se multiplica.']],comprobar:()=>v===l*h})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const l=r.entero(1,6),k=r.entero(0,6),v=pois(l,k);return prob({enunciado:`X ~ Poisson(λ = ${l}). ¿Cuánto vale P(X = ${k})? (4 decimales)`,v,dec:4,
      pasos:[paso('e^(−λ)λ^k',`e^(−${l}) × ${l}^${k}`,'Numerador.'),final('Entre k!',`÷ ${fact(k)} = ${marca(fmt(v,4))}`,'Probabilidad.')],errores:[[Math.exp(-l)*l**k,'Falta dividir entre k!.'],[l**k/fact(k),'Falta e^(−λ).']],comprobar:()=>cerca(v,k===0?Math.exp(-l):pois(l,k-1)*l/k)})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const l=r.entero(1,5),v=1-Math.exp(-l);return prob({enunciado:`X ~ Poisson(λ = ${l}). ¿Cuánto vale P(X ≥ 1)? (4 decimales)`,v,dec:4,
      pasos:[paso('Complemento','1 − P(X = 0)','Al menos uno.'),final('P(X = 0) = e^(−λ)',`1 − e^(−${l}) = ${marca(fmt(v,4))}`,'Probabilidad.')],errores:[[Math.exp(-l),'Esa es P(X = 0).'],[l,'Esa es la media.']],comprobar:()=>cerca(v,sum(Array.from({length:60},(_,k)=>pois(l,k+1))))})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const l=r.entero(2,8),k=r.entero(0,4),v=pois(l,k);return prob({enunciado:`Un centro de soporte recibe en promedio ${l} tickets por hora. ¿Qué probabilidad hay de recibir exactamente ${k} en una hora? (4 decimales)`,v,dec:4,
      pasos:[paso('Poisson',`λ = ${l}, k = ${k}`,'Eventos independientes con tasa fija.'),final('P(X = k)',marca(fmt(v,4)),'Probabilidad.')],errores:[[k/l,'No es una proporción simple.'],[Math.exp(-l),'Esa es la de cero tickets.']],comprobar:()=>cerca(v,pois(l,k))})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const l=r.entero(1,4),h=2,L=l*h,v=Math.exp(-L);return prob({enunciado:`Un servidor falla en promedio ${l} veces por semana. ¿Qué probabilidad hay de que no falle ninguna vez en ${h} semanas? (4 decimales)`,v,dec:4,
      pasos:[paso('Ajusta λ',`${l} × ${h} = ${L}`,'Dos semanas.'),final('P(X = 0) = e^(−λ)',`e^(−${L}) = ${marca(fmt(v,4))}`,'Ninguna falla.')],errores:[[Math.exp(-l),'λ debe ser para 2 semanas.'],[Math.exp(-l)**0.5,'Se multiplica λ, no se saca raíz.']],comprobar:()=>cerca(v,pois(l,0)**h)})}}
  }});

/* ---------- Normal ---------- */
const normal=crearGen({titulo:'Distribución normal',niveles:NIV,
  explicacion:'La normal N(μ, σ) es simétrica en forma de campana. Para comparar o calcular probabilidades se estandariza: <b>z = (x − μ)/σ</b> (cuántas desviaciones estándar está x de la media). Regla empírica: ≈ 68 % de los datos a ±1σ, 95 % a ±2σ y 99.7 % a ±3σ. P(X < x) = Φ(z), el área a la izquierda en la normal estándar.',
  alternativa:'z es como traducir a un idioma común: un 85 en un examen difícil puede ser mejor que un 90 en uno fácil; el z te dice qué tan lejos del promedio quedó cada uno.',
  referencia:'OpenIntro 4.1 – Distribución normal',regla:'z = (x − μ)/σ; P(X < x) = Φ(z); P(X > x) = 1 − Φ(z); 68–95–99.7 a ±1, 2 y 3σ.',pista:'Estandariza primero.',
  tarjetas:[['Valor z','z = (x − μ)/σ.'],['Regla empírica','68 % a ±1σ, 95 % a ±2σ, 99.7 % a ±3σ.'],['P(X > x)','1 − Φ(z).']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const mu=r.entero(50,100),s=r.entero(5,15),x=mu+r.entero(-3,3)*s+r.entero(-4,4),v=(x-mu)/s;return prob({enunciado:`X ~ N(μ = ${mu}, σ = ${s}). ¿Cuál es el valor z de x = ${x}? (2 decimales)`,v,dec:2,
      pasos:[paso('Resta la media',`${x} − ${mu} = ${x-mu}`,'Distancia a la media.'),final('Entre σ',`${x-mu} / ${s} = ${marca(fmt(v))}`,'Desviaciones estándar.')],errores:[[x-mu,'Falta dividir entre σ.'],[(mu-x)/s,'Es x − μ.']],comprobar:()=>cerca(mu+v*s,x)})}},
    b2:{prof:'basico',f:(n,r)=>{const k=r.elegir([1,2,3]),v=[0,68,95,99.7][k];return prob({enunciado:`Según la regla empírica, ¿qué porcentaje de los datos de una normal queda a ±${k} desviaciones estándar de la media?`,v,dec:1,unidad:'%',
      pasos:[paso('Regla 68–95–99.7',`±${k}σ`,'Aproximación.'),final('Porcentaje',marca(v)+' %','Regla empírica.')],errores:[[[68,95,99.7][(k)%3],'Revisa a cuántas σ.'],[100,'Nunca es exactamente 100 %.']].filter(([x])=>x!==v),comprobar:()=>Math.abs(100*(phi(k)-phi(-k))-v)<1})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const z=r.entero(-250,250)/100,v=phi(z);return prob({enunciado:`Con Z ~ N(0, 1), ¿cuánto vale P(Z < ${z})? (4 decimales)`,v,dec:4,
      pasos:[paso('Área a la izquierda',`Φ(${z})`,'Tabla o calculadora.'),final('Valor',marca(fmt(v,4)),z<0?'Menos de 0.5 (lado izquierdo).':'Más de 0.5.')],errores:[[1-v,'Esa es el área a la derecha.'],[z,'z no es una probabilidad.']],comprobar:()=>cerca(v,phiNum(z),1e-6)})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const mu=r.entero(60,90),s=r.entero(4,12),x=mu+r.entero(1,25),z=(x-mu)/s,v=1-phi(z);return prob({enunciado:`X ~ N(μ = ${mu}, σ = ${s}). ¿Cuánto vale P(X > ${x})? (4 decimales)`,v,dec:4,
      pasos:[paso('Estandariza',`z = (${x} − ${mu}) / ${s} = ${fmt(z,4)}`,'A la normal estándar.'),final('Área a la derecha',`1 − Φ(${fmt(z,4)}) = ${marca(fmt(v,4))}`,'Mayor que.')],errores:[[phi(z),'Esa es P(X < x).'],[z,'z no es una probabilidad.']],comprobar:()=>cerca(v,1-phiNum(z),1e-6)})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const mu=r.entero(160,175),s=r.entero(5,9),x=mu+r.entero(-12,12),v=phi((x-mu)/s);return prob({enunciado:`La estatura de los adultos de una ciudad es normal con media ${mu} cm y desviación ${s} cm. ¿Qué proporción mide menos de ${x} cm? (4 decimales)`,v,dec:4,
      pasos:[paso('z',`(${x} − ${mu}) / ${s} = ${fmt((x-mu)/s,4)}`,'Estandariza.'),final('Φ(z)',marca(fmt(v,4)),'Proporción.')],errores:[[1-v,'Esa es la proporción que mide más.'],[(x-mu)/s,'z no es la proporción.']],comprobar:()=>cerca(v,phiNum((x-mu)/s),1e-6)})}},
    a2:{prof:'aplicacion',f:(n,r)=>{let m1,s1,x1,m2,s2,x2,z1,z2;do{m1=r.entero(60,75);s1=r.entero(6,12);x1=m1+r.entero(5,20);m2=r.entero(70,85);s2=r.entero(4,10);x2=m2+r.entero(5,20);z1=(x1-m1)/s1;z2=(x2-m2)/s2}while(Math.abs(z1-z2)<0.05);const v=z1>z2?1:2;return prob({enunciado:`Examen 1: obtuviste ${x1} (media ${m1}, σ ${s1}). Examen 2: obtuviste ${x2} (media ${m2}, σ ${s2}). ¿En cuál te fue relativamente mejor? Escribe 1 o 2.`,v,dec:0,
      pasos:[paso('z de cada uno',`z₁ = ${fmt(z1,2)}, z₂ = ${fmt(z2,2)}`,'Se comparan en la misma escala.'),final('El z mayor',marca(v),'Mejor posición relativa.')],errores:[[3-v,'Compara los z, no las calificaciones.']],comprobar:()=>z1!==z2})}}
  }});

/* ---------- Teorema del límite central ---------- */
const tlc=crearGen({titulo:'Teorema del límite central',niveles:NIV,
  explicacion:'Si tomas muestras de tamaño n (suficientemente grande, por ejemplo n ≥ 30) de cualquier población con media μ y desviación σ, la <b>media muestral</b> x̄ se distribuye aproximadamente normal con media μ y <b>error estándar</b> SE = σ/√n. Por eso las medias son más estables que los datos sueltos: cuadruplicar n reduce el SE a la mitad.',
  alternativa:'Un dato suelto puede ser raro, pero el promedio de muchos tiende a quedarse cerca de la media real; cuantos más datos promedias, menos se mueve.',
  referencia:'OpenIntro 5.1 – Estimaciones puntuales y variabilidad muestral',regla:'x̄ ≈ N(μ, σ/√n) para n grande; SE = σ/√n; z = (x̄ − μ)/SE.',pista:'Usa σ/√n, no σ.',
  tarjetas:[['Error estándar de la media','σ/√n.'],['Qué dice el TLC','La media muestral es aproximadamente normal para n grande.'],['Para reducir el SE a la mitad','Cuadruplica n.']],
  plantillas:{
    b1:{prof:'basico',f:(n,r)=>{const s=r.entero(5,40),nn=r.elegir([16,25,36,49,64,100]),v=s/Math.sqrt(nn);return prob({enunciado:`σ = ${s} y n = ${nn}. ¿Cuál es el error estándar de la media? (2 decimales)`,v,dec:2,pasos:[paso('SE = σ/√n',`${s} / √${nn} = ${s} / ${Math.sqrt(nn)}`,'Raíz de n.'),final('Calcula',marca(fmt(v)),'Error estándar.')],errores:[[s/nn,'Se divide entre √n, no entre n.'],[s,'Esa es la σ de los datos.']],comprobar:()=>cerca(v*v*nn,s*s)})}},
    b2:{prof:'basico',f:(n,r)=>{const k=r.elegir([4,9,16]),v=1/Math.sqrt(k);return prob({enunciado:`Si multiplicas el tamaño de muestra por ${k}, ¿por cuánto se multiplica el error estándar? (4 decimales)`,v,dec:4,pasos:[paso('SE ∝ 1/√n',`1/√${k}`,'Raíz.'),final('Factor',marca(fmt(v,4)),'Se reduce.')],errores:[[1/k,'Es 1/√k, no 1/k.'],[k,'El SE baja, no sube.']],comprobar:()=>cerca(v*Math.sqrt(k),1)})}},
    p1:{prof:'procedimiento',f:(n,r)=>{const mu=r.entero(50,200),s=r.entero(10,40),nn=r.elegir([25,36,49,64,100]),x=mu+r.entero(1,10),se=s/Math.sqrt(nn),v=(x-mu)/se;return prob({enunciado:`μ = ${mu}, σ = ${s}, n = ${nn}. ¿Cuál es el z de una media muestral x̄ = ${x}? (2 decimales)`,v,dec:2,
      pasos:[paso('SE',`${s}/√${nn} = ${fmt(se,4)}`,'Error estándar.'),final('z',`(${x} − ${mu}) / ${fmt(se,4)} = ${marca(fmt(v))}`,'Con el SE, no con σ.')],errores:[[(x-mu)/s,'Para una media se usa σ/√n.'],[x-mu,'Falta dividir.']],comprobar:()=>cerca(v*s,(x-mu)*Math.sqrt(nn))})}},
    p2:{prof:'procedimiento',f:(n,r)=>{const mu=r.entero(50,200),s=r.entero(10,40),nn=r.elegir([25,36,49,64,100]),x=mu+r.entero(1,8),z=(x-mu)/(s/Math.sqrt(nn)),v=1-phi(z);return prob({enunciado:`μ = ${mu}, σ = ${s}, n = ${nn}. ¿Qué probabilidad hay de que la media muestral supere ${x}? (4 decimales)`,v,dec:4,
      pasos:[paso('z con el SE',`z = (${x} − ${mu})/(${s}/√${nn}) = ${fmt(z,4)}`,'TLC.'),final('1 − Φ(z)',marca(fmt(v,4)),'Área a la derecha.')],errores:[[1-phi((x-mu)/s),'Para la media se usa σ/√n.'],[phi(z),'Esa es la de ser menor.']],comprobar:()=>cerca(v,1-phiNum(z),1e-6)})}},
    a1:{prof:'aplicacion',f:(n,r)=>{const mu=r.entero(300,500),s=r.entero(40,120),nn=r.elegir([36,49,64,100]),v=s/Math.sqrt(nn);return prob({enunciado:`El gasto por cliente tiene media $${mu} y desviación $${s}. Si tomas muestras de ${nn} clientes, ¿cuál es el error estándar del gasto promedio? (2 decimales)`,v,dec:2,unidad:'pesos',
      pasos:[paso('SE = σ/√n',`${s}/√${nn}`,'Variabilidad de la media.'),final('Calcula',marca(fmt(v)),'Mucho menor que σ.')],errores:[[s,'Esa es la del gasto individual.'],[s/nn,'Se divide entre √n.']],comprobar:()=>cerca(v*Math.sqrt(nn),s)})}},
    a2:{prof:'aplicacion',f:(n,r)=>{const mu=r.entero(400,600),s=r.entero(50,150),nn=r.elegir([36,64,100]),x=mu-r.entero(5,25),z=(x-mu)/(s/Math.sqrt(nn)),v=phi(z);return prob({enunciado:`Una máquina llena bolsas con media ${mu} g y σ ${s} g. Un inspector pesa ${nn} bolsas. ¿Qué probabilidad hay de que el promedio quede por debajo de ${x} g? (4 decimales)`,v,dec:4,
      pasos:[paso('SE y z',`SE = ${s}/√${nn} = ${fmt(s/Math.sqrt(nn),3)}; z = ${fmt(z,3)}`,'TLC.'),final('Φ(z)',marca(fmt(v,4)),'Probabilidad.')],errores:[[phi((x-mu)/s),'Para el promedio se usa el SE.'],[1-v,'Es «por debajo»: área a la izquierda.']],comprobar:()=>cerca(v,phiNum(z),1e-6)})}}
  }});

export default {'est/variables':variables,'est/muestreo':muestreo,'est/frecuencias':frecuencias,'est/histogramas':histogramas,'est/correlacion':correlacion,
  'prob/conteo':conteo,'prob/bayes':bayes,'prob/va':va,'prob/binomial':binomial,'prob/poisson':poisson,'prob/normal':normal,'prob/tlc':tlc};
